-- Atualização de preços de venda a partir do PDV (Listagem de Preços de 06/11/2026).
-- Altera SOMENTE mn_products.sale_cents (e updated_at) dos produtos já salvos pelo painel.
-- Produtos que nunca foram editados no painel usam o catálogo do código e já recebem o novo preço com a implantação.
-- Não altera nome, custo, categoria, foto, disponibilidade, pedidos ou histórico financeiro.
-- Granel: sale_cents fica em centavos por kg (a vitrine mostra por 100 g). Unidade: centavos por unidade.
-- Cada alteração gera um registro em mn_audit (evento product.price_import). Pode ser importado mais de uma vez sem efeito duplicado.

START TRANSACTION;
SET @mn_agora = ROUND(UNIX_TIMESTAMP(NOW(3)) * 1000);

INSERT INTO mn_audit(event,entity_id,details,created_at) SELECT 'product.price_import', id, CONCAT('{"previousPriceCents":', sale_cents, ',"priceCents":6000,"source":"PDV 06/11/2026"}'), @mn_agora FROM mn_products WHERE id='prod-92' AND is_bulk=1 AND sale_cents<>6000;
UPDATE mn_products SET sale_cents=6000, updated_at=@mn_agora WHERE id='prod-92' AND is_bulk=1 AND sale_cents<>6000;
